import numpy as npfrom optproblem_class import OptProblemfrom rosenbrock import rosenbrock, rosenbrock_gradfrom quasinewton_methods import GoodBroyden, BadBroyden, SymmetricBroyden, BFGS, DFPimport scipyrosen_prob=OptProblem(    rosenbrock,    input_shape=2,    grad=rosenbrock_grad)def testing(prob, name, ):    print(name)    verbose_value = False        x0 = np.random.randint(-100, 100, size = prob.input_shape)    print("     initial value", x0)        solve_kwargs = {        "x0" : x0,        "residual_tol" : 1e-12,        "cauchy_tol" : 1e-12,        "max_steps" : 1000    }    print("     Good Broyden:", GoodBroyden(prob, verbose=verbose_value).solve(**solve_kwargs))    print("     Bad Broyden", BadBroyden(prob, verbose=verbose_value).solve(**solve_kwargs))    print("     Symmetric Broyden", SymmetricBroyden(prob, verbose=verbose_value).solve(**solve_kwargs))    print("     DFP", DFP(prob, verbose=verbose_value).solve(**solve_kwargs))    print("     BFGS", BFGS(prob, verbose=verbose_value).solve(**solve_kwargs))    print("     Scipy", scipy.optimize.fmin_bfgs(prob.f,        x0,        fprime=prob.grad,        disp=False,        maxiter=500        ))# 1. Convex quadratic: the sanity checkA = np.array([[4.0, 1.0], [1.0, 3.0]])b = np.array([1.0, 2.0])quad = OptProblem(lambda x: 0.5 * x @ A @ x - b @ x, 2,                  grad=lambda x: A @ x - b)# minimum is [0.09090909, 0.63636364]# minimum: np.linalg.solve(A, b)testing(quad, "Normal quadratic")# 2. Himmelblau: four minima, so it tests where you end updef himmelblau(x):    return (x[0]**2 + x[1] - 11)**2 + (x[0] + x[1]**2 - 7)**2def himmelblau_grad(x):    a = x[0]**2 + x[1] - 11    c = x[0] + x[1]**2 - 7    return np.array([4*x[0]*a + 2*c, 2*a + 4*x[1]*c])himmel = OptProblem(himmelblau, 2, grad=himmelblau_grad)# minima: (3,2), (-2.8051,3.1313), (-3.7793,-3.2832), (3.5844,-1.8481)# Only Bad Broyden does not testing(himmel, "Himmelblau")# 3. Beale: flat, narrow valley, minimum at (3, 0.5)def beale(x):    a = 1.5 - x[0] + x[0]*x[1]    b = 2.25 - x[0] + x[0]*x[1]**2    c = 2.625 - x[0] + x[0]*x[1]**3    return a**2 + b**2 + c**2def beale_grad(x):    a = 1.5 - x[0] + x[0]*x[1]    b = 2.25 - x[0] + x[0]*x[1]**2    c = 2.625 - x[0] + x[0]*x[1]**3    return np.array([        2*a*(x[1]-1) + 2*b*(x[1]**2-1) + 2*c*(x[1]**3-1),        2*a*x[0] + 4*b*x[0]*x[1] + 6*c*x[0]*x[1]**2])beale_prob = OptProblem(beale, 2, grad=beale_grad)testing(beale_prob, "Beale")# 4. n-dimensional Rosenbrock: tests scaling, minimum at all onesdef rosen_n(x):    return np.sum(100*(x[1:] - x[:-1]**2)**2 + (1 - x[:-1])**2)def rosen_n_grad(x):    g = np.zeros_like(x, dtype=float)    g[:-1] += -400*x[:-1]*(x[1:] - x[:-1]**2) - 2*(1 - x[:-1])    g[1:]  += 200*(x[1:] - x[:-1]**2)    return grosen5 = OptProblem(rosen_n, 5, grad=rosen_n_grad)testing(rosen5, "Rosenbrock, 5 dim")